INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "王章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州南乐人，曾任孔目官，随刘知远到太原。947年任权三司使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "154bd412-f052-5459-9c17-951cfcd91759"}, {"name": "李存勖", "aliases": ["李存勗", "李亚子", "后唐庄宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "biography": "908年继承晋王之位，923年在魏州称帝，国号唐；同年率军灭后梁。", "status": "draft", "id": "4e068da9-c8dd-5a31-a747-87669e3bf993"}, {"name": "李嗣源", "aliases": ["李亶", "后唐明宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "biography": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "status": "draft", "id": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "李崇矩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上党人，史弘肇的亲吏，曾掌其家产账册。951年郭威命他寻找史弘肇亲属，他找到史弘福并将所掌家产全部交还；郭威赞赏他，令他转隶柴荣帐下。生卒年未载。", "biography": null, "status": "draft", "id": "66c2a5b6-64bc-5334-98dd-92a9f59a0020"}, {"name": "史弘福", "aliases": ["史福"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "史弘肇的弟弟。951年李崇矩向郭威报告他仍在世，并将掌握的史氏家产全部交给他。《宋史》李崇矩传写史弘肇母弟福。生卒年未载。", "biography": null, "status": "draft", "id": "97eefc25-d736-5717-b5a9-5470fa647e73"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "刘承勋", "aliases": ["劉承勛", "劉承勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘承祐的弟弟。950年五月以山南西道节度使身份被任命为开封尹，加兼中书令；《资治通鉴》同时说明他实际尚未出阁。与947年已去世的刘承训分开，生卒年未载。", "biography": null, "status": "draft", "id": "3f17d043-13b1-5bdf-bd39-715c053074f4"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "刘皞（后晋编敕官）", "aliases": ["刘皞", "劉皞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。《旧五代史》记载，938年七月以驾部员外郎兼侍御史知杂事的身份参与编订唐明宗时期的诏敕。生卒年未载。", "biography": null, "status": "draft", "id": "c44bce1e-a8e2-5c68-adc3-bc8a4c48978f"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

